SELECT md.chembl_id AS compound_chembl_id, cs.canonical_smiles, cr.compound_key, COALESCE(CAST(d.pubmed_id AS TEXT), d.doi) AS pubmed_id_or_doi, a.description AS assay_description, act.standard_type, act.standard_relation, act.standard_value, act.standard_units, act.activity_comment, td.chembl_id AS target_chembl_id, td.pref_name AS target_name, td.organism AS target_organism FROM assays a JOIN activities act ON a.assay_id = act.assay_id JOIN target_dictionary td ON a.tid = td.tid JOIN compound_records cr ON act.record_id = cr.record_id JOIN molecule_dictionary md ON cr.molregno = md.molregno JOIN compound_structures cs ON md.molregno = cs.molregno JOIN docs d ON cr.doc_id = d.doc_id WHERE a.chembl_id = 'CHEMBL1865' AND act.standard_type = 'IC50' AND d.pubmed_id IS NOT NULL
